package com.mr91.wealth;

import android.app.*;
import android.os.Bundle;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.content.*;
import android.text.InputType;
import android.widget.*;
import org.json.*;
import java.text.NumberFormat;
import java.util.*;

public class MainActivity extends Activity {
  private static final int BG=Color.rgb(11,18,32), CARD=Color.rgb(20,30,49), CARD2=Color.rgb(26,39,61), TEXT=Color.rgb(239,245,255), MUTED=Color.rgb(155,174,199), TEAL=Color.rgb(56,217,196), RED=Color.rgb(255,111,125), GREEN=Color.rgb(76,220,159), BLUE=Color.rgb(93,157,255);
  private LinearLayout root, content, nav; private String page="خانه"; private JSONObject data; private final NumberFormat nf=NumberFormat.getInstance(new Locale("fa","IR"));
  @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG); load(); render();}
  private void load(){ try {String s=getSharedPreferences("mr91",0).getString("data",null); if(s!=null)data=new JSONObject(s);}catch(Exception ignored){} if(data==null){data=new JSONObject();try{data.put("accounts",new JSONArray().put(new JSONObject().put("name","کیف پول").put("balance",0)).put(new JSONObject().put("name","حساب اصلی").put("balance",0)));data.put("transactions",new JSONArray());data.put("goals",new JSONArray());data.put("budgets",new JSONArray());data.put("debts",new JSONArray());data.put("currency","تومان");}catch(Exception ignored){} save();}}
  private void save(){getSharedPreferences("mr91",0).edit().putString("data",data.toString()).apply();}
  private JSONArray arr(String k){JSONArray a=data.optJSONArray(k);return a==null?new JSONArray():a;}
  private String money(long n){return nf.format(n)+" تومان";}
  private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
  private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setGravity(Gravity.RIGHT);t.setTextDirection(View.TEXT_DIRECTION_RTL);return t;}
  private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
  private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
  private void pad(View v,int n){v.setPadding(n,n,n,n);}
  private void add(LinearLayout p,View v,int h){p.addView(v,new LinearLayout.LayoutParams(-1,h));}
  private TextView button(String s,int color){TextView b=text(s,14, color==TEAL?BG:TEXT,true);b.setGravity(Gravity.CENTER);b.setPadding(12,13,12,13);b.setBackground(shape(color,24));return b;}
  private void card(LinearLayout parent,View child){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,12);child.setPadding(16,16,16,16);child.setBackground(shape(CARD,24));parent.addView(child,lp);}
  private void gap(LinearLayout p,int h){View v=new View(this);p.addView(v,new LinearLayout.LayoutParams(1,h));}
  private void render(){
    root=column();root.setBackgroundColor(BG);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);setContentView(root);
    LinearLayout header=row();header.setPadding(18,18,18,10);TextView logo=text("MR91  |  Wealth",20,TEAL,true);logo.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);header.addView(logo,new LinearLayout.LayoutParams(0,52,1));TextView plus=button("+ تراکنش",TEAL);plus.setOnClickListener(v->txDialog(null));header.addView(plus);root.addView(header);
    ScrollView scroll=new ScrollView(this);content=column();content.setPadding(16,8,16,16);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));renderPage();
    nav=row();nav.setPadding(6,8,6,10);nav.setBackgroundColor(CARD);String[] names={"خانه","تراکنش‌ها","تقویم","مدیریت","تنظیمات"};for(String n:names){TextView b=text(n,11,page.equals(n)?TEAL:MUTED,true);b.setGravity(Gravity.CENTER);b.setPadding(2,12,2,12);nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->{page=n;render();});}root.addView(nav);
  }
  private long totalBalance(){long n=0;JSONArray a=arr("accounts");for(int i=0;i<a.length();i++){JSONObject account=a.optJSONObject(i);if(account!=null)n+=account.optLong("balance");}return n;}
  private void adjustAccount(String accountName,long delta){JSONArray accounts=arr("accounts");if(accounts.length()==0){try{accounts.put(new JSONObject().put("name",accountName==null||accountName.isEmpty()?"حساب اصلی":accountName).put("balance",delta));data.put("accounts",accounts);}catch(Exception ignored){}return;}boolean found=false;for(int i=0;i<accounts.length();i++){JSONObject a=accounts.optJSONObject(i);if(a!=null&&a.optString("name").equals(accountName)){try{a.put("balance",a.optLong("balance")+delta);}catch(Exception ignored){}found=true;break;}}if(!found){JSONObject a=accounts.optJSONObject(0);if(a!=null)try{a.put("balance",a.optLong("balance")+delta);}catch(Exception ignored){}}try{data.put("accounts",accounts);}catch(Exception ignored){}}
  private void title(String s,String sub){content.addView(text(s,22,TEXT,true));if(sub!=null){gap(content,4);content.addView(text(sub,12,MUTED,false));}gap(content,14);}
  private void renderPage(){switch(page){case "خانه":home();break;case "تراکنش‌ها":transactions();break;case "تقویم":calendar();break;case "مدیریت":manage();break;default:settings();}}
  private void home(){title("داشبورد مالی","نمای کلی وضعیت پولت");LinearLayout hero=column();hero.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(18,55,77),Color.rgb(18,35,57)}));hero.setCornerRadius(26);hero.setPadding(18,20,18,20);hero.addView(text("موجودی کل",13,MUTED,false));gap(hero,6);hero.addView(text(money(totalBalance()),27,TEXT,true));gap(hero,8);hero.addView(text("اطلاعات فقط روی همین گوشی ذخیره می‌شود",11,TEAL,false));card(content,hero);
    long inc=0,exp=0;JSONArray ts=arr("transactions");for(int i=0;i<ts.length();i++){JSONObject t=ts.optJSONObject(i);if(t.optString("type").equals("درآمد"))inc+=t.optLong("amount");else exp+=t.optLong("amount");}
    LinearLayout stats=row();stats.addView(stat("کل درآمد",money(inc),GREEN),new LinearLayout.LayoutParams(0,-2,1));View spacer=new View(this);stats.addView(spacer,new LinearLayout.LayoutParams(10,1));stats.addView(stat("کل هزینه",money(exp),RED),new LinearLayout.LayoutParams(0,-2,1));content.addView(stats);gap(content,12);
    LinearLayout quick=row();TextView in=button("＋ ثبت درآمد",GREEN),out=button("－ ثبت هزینه",RED);quick.addView(in,new LinearLayout.LayoutParams(0,-2,1));View sp=new View(this);quick.addView(sp,new LinearLayout.LayoutParams(8,1));quick.addView(out,new LinearLayout.LayoutParams(0,-2,1));content.addView(quick);in.setOnClickListener(v->txDialog("درآمد"));out.setOnClickListener(v->txDialog("هزینه"));gap(content,18);
    content.addView(text("حساب‌ها",18,TEXT,true));gap(content,8);JSONArray ac=arr("accounts");for(int i=0;i<ac.length();i++){JSONObject a=ac.optJSONObject(i);LinearLayout c=column();c.addView(text(a.optString("name"),14,TEXT,true));gap(c,5);c.addView(text(money(a.optLong("balance")),17,TEAL,true));card(content,c);}content.addView(text("آخرین تراکنش‌ها",18,TEXT,true));gap(content,8);showTxList(5);
  }
  private View stat(String label,String val,int tone){LinearLayout c=column();c.setPadding(13,15,13,15);c.setBackground(shape(CARD,20));c.addView(text(label,12,MUTED,false));gap(c,8);c.addView(text(val,14,tone,true));return c;}
  private void transactions(){title("تراکنش‌ها","درآمدها و هزینه‌های ثبت‌شده");TextView b=button("＋ ثبت تراکنش جدید",TEAL);add(content,b,-2);b.setOnClickListener(v->txDialog(null));gap(content,12);showTxList(1000);}
  private void showTxList(int limit){JSONArray a=arr("transactions");if(a.length()==0){content.addView(text("هنوز تراکنشی ثبت نکردی. از دکمه بالا شروع کن.",14,MUTED,false));return;}for(int i=a.length()-1,shown=0;i>=0&&shown<limit;i--,shown++){final int txIndex=i;JSONObject t=a.optJSONObject(i);LinearLayout r=row();LinearLayout info=column();info.addView(text(t.optString("title"),14,TEXT,true));gap(info,5);info.addView(text(t.optString("category","سایر")+"  •  "+t.optString("date","امروز"),11,MUTED,false));r.addView(info,new LinearLayout.LayoutParams(0,-2,1));boolean income=t.optString("type").equals("درآمد");r.addView(text((income?"+ ":"− ")+money(t.optLong("amount")),13,income?GREEN:RED,true));card(content,r);r.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle("حذف تراکنش؟").setMessage(t.optString("title")).setNegativeButton("لغو",null).setPositiveButton("حذف",(d,w)->{JSONArray fresh=new JSONArray();JSONArray old=arr("transactions");JSONObject removed=old.optJSONObject(txIndex);if(removed!=null){long amount=removed.optLong("amount");adjustAccount(removed.optString("account",""),removed.optString("type").equals("درآمد")?-amount:amount);}for(int j=0;j<old.length();j++)if(j!=txIndex)fresh.put(old.optJSONObject(j));try{data.put("transactions",fresh);}catch(Exception ignored){}save();render();}).show();return true;});}}
  private void txDialog(String initial){LinearLayout box=column();box.setPadding(6,4,6,4);EditText title=field("عنوان تراکنش");EditText amount=field("مبلغ به تومان");amount.setInputType(InputType.TYPE_CLASS_NUMBER);EditText category=field("دسته‌بندی (مثلاً خوراک، حقوق)");EditText date=field("تاریخ (مثلاً امروز یا 1405/07/30)");Spinner type=new Spinner(this);String[] types={"هزینه","درآمد"};type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,types));if(initial!=null)type.setSelection(initial.equals("درآمد")?1:0);box.addView(type);box.addView(title);box.addView(amount);box.addView(category);box.addView(date);new AlertDialog.Builder(this).setTitle("ثبت تراکنش").setView(box).setNegativeButton("لغو",null).setPositiveButton("ذخیره",(d,w)->{try{long amt=Long.parseLong(amount.getText().toString().trim());if(amt<=0||title.getText().toString().trim().isEmpty())throw new Exception();JSONObject t=new JSONObject();t.put("title",title.getText().toString().trim());t.put("amount",amt);t.put("type",type.getSelectedItem().toString());t.put("category",category.getText().toString().trim().isEmpty()?"سایر":category.getText().toString().trim());t.put("date",date.getText().toString().trim().isEmpty()?"امروز":date.getText().toString().trim());JSONArray accounts=arr("accounts");String accountName=accounts.length()>0&&accounts.optJSONObject(0)!=null?accounts.optJSONObject(0).optString("name","حساب اصلی"):"حساب اصلی";t.put("account",accountName);JSONArray a=arr("transactions");a.put(t);data.put("transactions",a);adjustAccount(accountName,t.optString("type").equals("درآمد")?amt:-amt);save();render();Toast.makeText(this,"تراکنش ذخیره شد",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"عنوان و مبلغ معتبر وارد کن",Toast.LENGTH_LONG).show();}}).show();}
  private EditText field(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setTextColor(TEXT);e.setHintTextColor(MUTED);e.setTextDirection(View.TEXT_DIRECTION_RTL);e.setPadding(12,8,12,8);return e;}
  private void calendar(){title("تقویم مالی","تاریخ‌های ثبت‌شده در تراکنش‌ها");content.addView(text("تاریخ تراکنش را هنگام ثبت می‌توانی به‌شکل شمسی وارد کنی؛ این بخش فعلاً تقویم ماهانهٔ شبکه‌ای نیست.",14,TEAL,false));gap(content,10);gap(content,16);showTxList(1000);}
  private void manage(){title("مدیریت مالی","حساب‌ها، اهداف، بودجه و بدهی‌ها");sectionAdd("حساب جدید","accounts","نام حساب","موجودی اولیه", "balance");sectionAdd("هدف پس‌انداز","goals","عنوان هدف","مبلغ هدف","target");sectionAdd("بودجه ماهانه","budgets","دسته هزینه","سقف بودجه","limit");sectionAdd("بدهی یا وام","debts","به چه کسی بدهکاری؟","مبلغ کل بدهی","total");}
  private void sectionAdd(String label,String key,String hint1,String hint2,String numericKey){LinearLayout c=column();TextView h=text(label,16,TEXT,true);c.addView(h);gap(c,8);LinearLayout r=row();TextView add=button("+ افزودن",TEAL);r.addView(add,new LinearLayout.LayoutParams(0,-2,1));TextView count=text("تعداد: "+arr(key).length(),12,MUTED,false);count.setGravity(Gravity.CENTER);r.addView(count,new LinearLayout.LayoutParams(0,-2,1));c.addView(r);JSONArray a=arr(key);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);gap(c,8);c.addView(text(o.optString("name",o.optString("title",o.optString("category",o.optString("creditor","مورد"))))+"  ·  "+money(o.optLong(numericKey)),12,MUTED,false));}card(content,c);add.setOnClickListener(v->manageDialog(label,key,hint1,hint2,numericKey));}
  private void manageDialog(String label,String key,String h1,String h2,String nk){LinearLayout box=column();EditText name=field(h1);EditText value=field(h2+" (تومان)");value.setInputType(InputType.TYPE_CLASS_NUMBER);box.addView(name);box.addView(value);new AlertDialog.Builder(this).setTitle(label).setView(box).setNegativeButton("لغو",null).setPositiveButton("ذخیره",(d,w)->{try{long n=Long.parseLong(value.getText().toString());if(name.getText().toString().trim().isEmpty()||n<0)throw new Exception();JSONObject o=new JSONObject();String prop=key.equals("accounts")?"name":key.equals("goals")?"title":key.equals("budgets")?"category":"creditor";o.put(prop,name.getText().toString().trim());o.put(nk,n);if(key.equals("accounts"))o.put("balance",n);if(key.equals("goals"))o.put("current",0);if(key.equals("debts")){o.put("paid",0);o.put("installments",1);}JSONArray a=arr(key);a.put(o);data.put(key,a);save();render();}catch(Exception e){Toast.makeText(this,"مقادیر معتبر وارد کن",Toast.LENGTH_SHORT).show();}}).show();}
  private void settings(){title("تنظیمات","مدیریت اطلاعات و حریم خصوصی");TextView export=button("اشتراک‌گذاری نسخه پشتیبان JSON",TEAL);card(content,export);export.setOnClickListener(v->{Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("application/json");intent.putExtra(Intent.EXTRA_SUBJECT,"MR91 Wealth Backup");intent.putExtra(Intent.EXTRA_TEXT,data.toString());startActivity(Intent.createChooser(intent,"ارسال یا ذخیرهٔ پشتیبان"));});TextView reset=button("پاک کردن همه اطلاعات",RED);card(content,reset);reset.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("پاک کردن اطلاعات؟").setMessage("این کار تراکنش‌ها، حساب‌ها و اهداف را حذف می‌کند.").setNegativeButton("لغو",null).setPositiveButton("پاک کن",(d,w)->{getSharedPreferences("mr91",0).edit().clear().apply();data=null;load();render();}).show());content.addView(text("MR91 Wealth 1.0\nنسخه آزمایشی بومی اندروید\n\nتمام داده‌ها روی دستگاه ذخیره می‌شوند. هیچ دسترسی پیامک، حساب بانکی یا اینترنتی استفاده نمی‌شود.",13,MUTED,false));}
}
